@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/exampleWebAPI_354btrh> ;
            sh:resultMessage "A WebAPI node must specify a service type with a string, IRI, or DefinedTerm" ;
            sh:resultPath schema1:serviceType ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape [ sh:message "A WebAPI node must specify a service type with a string, IRI, or DefinedTerm" ;
                    sh:minCount 1 ;
                    sh:or ( [ sh:nodeKind sh:IRI ] [ sh:class schema1:DefinedTerm ] [ sh:datatype xsd:string ;
                                sh:minLength 3 ] ) ;
                    sh:path schema1:serviceType ] ;
            sh:value "" ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .

